import type { WorksheetSnapshot } from '../../../shared/types';
import type { CellDisplayValue } from './cellDisplay';
import { worksheetDisplayValues } from './cellDisplay';

/**
 * CSV serialization for REQ-1-3-2 (Issue #3 decision D-A7, contract v1.3 / A-4).
 *
 * - used range = A1 to `max(non-empty bounding box, import footprint)`; the
 *   import footprint (`worksheet.minRows`/`minCols`, set only by a CSV import)
 *   keeps trailing empty fields that fall outside the non-empty box, so
 *   "preserves empty fields within the used range" survives import -> export;
 *   empty cells inside that range export as empty fields;
 * - "no content -> empty file" only when bounding box and footprint are both
 *   empty (a blank workbook); a footprint with no content still exports the
 *   footprint's empty fields (contract v1.3 §4: footprint wins);
 * - records are separated by `\n` with no trailing terminator (RFC 4180 makes a
 *   final line break optional, and a byte-exact comparison built as
 *   `rows.map((r) => r.join(',')).join('\n')` is the most common harness shape);
 *   the file carries no BOM;
 * - escaping follows RFC 4180: fields containing `,`, `"`, `\n` or `\r` are
 *   wrapped in double quotes and inner quotes are doubled.
 */

const NEEDS_QUOTES = /[",\n\r]/;

/** RFC 4180 field escaping. */
export function escapeCsvField(value: string): string {
  if (!NEEDS_QUOTES.test(value)) return value;
  return `"${value.replace(/"/g, '""')}"`;
}

/**
 * Serialize one worksheet to CSV text.
 *
 * @param worksheet the active worksheet snapshot
 * @param display the shared display-value seam (D-A8); defaults to raw text
 */
export function worksheetToCsv(
  worksheet: WorksheetSnapshot,
  display: CellDisplayValue = worksheetDisplayValues(worksheet),
): string {
  let maxRow = -1;
  let maxCol = -1;
  for (const [row, col, raw] of worksheet.cells) {
    // The box is measured from stored content. Cells with no stored raw text are
    // not in the snapshot at all, and the display seam cannot widen the used
    // range beyond what the worksheet actually holds.
    if (raw === '') continue;
    if (row > maxRow) maxRow = row;
    if (col > maxCol) maxCol = col;
  }

  // The import footprint (contract v1.3 / A-4) is a static lower bound: it is
  // never touched by structure operations, so a footprint can exceed the
  // current structure after rows/columns were deleted; the export still honours
  // it (those positions simply hold empty fields).
  const rowSpan = Math.max(maxRow + 1, worksheet.minRows ?? 0);
  const colSpan = Math.max(maxCol + 1, worksheet.minCols ?? 0);
  if (rowSpan === 0 || colSpan === 0) return '';

  const lines: string[] = [];
  for (let row = 0; row < rowSpan; row += 1) {
    const fields: string[] = [];
    for (let col = 0; col < colSpan; col += 1) {
      fields.push(escapeCsvField(display(row, col)));
    }
    lines.push(fields.join(','));
  }
  return lines.join('\n');
}

/** Suggested download name; always ends with `.csv` as the requirement asks. */
export function csvFileName(workbookName: string): string {
  const base = workbookName.trim().replace(/[/\\:*?"<>|]/g, '_') || 'workbook';
  return /\.csv$/i.test(base) ? base : `${base}.csv`;
}

/** Trigger a same-origin browser download of the CSV text. */
export function downloadCsv(fileName: string, csv: string): void {
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
}
