  async (action: () => Promise<WorkbookSnapshot>) => {
    setEditing(null);
    try {
      applySnapshot(await action());
      setErrorMessage(null);
    } catch (error: unknown) {
      setErrorMessage(messageOf(error));
    }
  },
  [applySnapshot],
);

// Single display-value seam (D-A8): the grid and the CSV export read the same
// function, so sub-issue C only has to replace `worksheetDisplayValues`.
const displayValue = useMemo(
  () => (activeWorksheet ? worksheetDisplayValues(activeWorksheet) : () => ''),
  [activeWorksheet],
);

